module rational_to_fraction (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [9:0] integer_part,\n    input wire [43:0] digits_packed,\n    input wire [3:0] L,\n    input wire [3:0] R,\n    output reg [63:0] numerator,\n    output reg [63:0] denominator,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] COMPUTE_A     = 3'd1;\n    localparam [2:0] COMPUTE_B     = 3'd2;\n    localparam [2:0] COMPUTE_DENOM = 3'd3;\n    localparam [2:0] COMPUTE_NUM   = 3'd4;\n    localparam [2:0] FINISH        = 3'd5;\n\n    reg [2:0] state;\n\n    // Computation registers\n    reg [9:0] int_part_reg;\n    reg [43:0] digits_reg;\n    reg [3:0] L_reg;\n    reg [3:0] R_reg;\n    reg [3:0] K;\n    reg [3:0] i;\n    reg [3:0] j;\n    reg [63:0] A;\n    reg [63:0] B;\n    reg [63:0] pow10_K;\n    reg [63:0] pow10_R;\n    reg [63:0] num_temp;\n    reg [63:0] denom_temp;\n\n    // Combined digit array\n    wire [3:0] digit_array [0:10];\n    genvar idx;\n    generate\n        for (idx = 0; idx <= 10; idx = idx + 1) begin : digit_gen\n            assign digit_array[idx] = (digits_reg >> (44 - (idx+1)*4)) & 4'hF;\n        end\n    endgenerate\n\n    // FSM next state logic\n    always @(*) begin\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    if (L_reg > R_reg) state = COMPUTE_A;\n                    else state = COMPUTE_B;\n                end\n                else state = IDLE;\n            end\n            COMPUTE_A: state = (i < K - 1) ? COMPUTE_A : COMPUTE_B;\n            COMPUTE_B: state = (j < R_reg) ? COMPUTE_B : COMPUTE_DENOM;\n            COMPUTE_DENOM: state = COMPUTE_NUM;\n            COMPUTE_NUM: state = FINISH;\n            FINISH: state = IDLE;\n            default: state = IDLE;\n        endcase\n    end\n\n    // FSM sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            int_part_reg <= 10'd0;\n            digits_reg <= 44'd0;\n            L_reg <= 4'd0;\n            R_reg <= 4'd0;\n            K <= 4'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            A <= 64'd0;\n            B <= 64'd0;\n            pow10_K <= 64'd0;\n            pow10_R <= 64'd0;\n            num_temp <= 64'd0;\n            denom_temp <= 64'd0;\n            numerator <= 64'd0;\n            denominator <= 64'd0;\n            done <= 1'b0;\n        end\n        else begin\n            done <= 1'b0;\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        int_part_reg <= integer_part;\n                        digits_reg <= digits_packed;\n                        L_reg <= L;\n                        R_reg <= R;\n                        K <= L - R;\n                        i <= 4'd0;\n                        j <= 4'd0;\n                        A <= 64'd0;\n                        B <= 64'd0;\n                    end\n                end\n                COMPUTE_A: begin\n                    A <= (A * 64'd10) + {{60{1'b0}}, digit_array[i]};\n                    i <= i + 1;\n                end\n                COMPUTE_B: begin\n                    B <= (B * 64'd10) + {{60{1'b0}}, digit_array[K + j]};\n                    j <= j + 1;\n                end\n                COMPUTE_DENOM: begin\n                    pow10_K <= pow10_func(K);\n                    pow10_R <= pow10_func(R_reg);\n                end\n                COMPUTE_NUM: begin\n                    denom_temp <= pow10_K * (pow10_R - 64'd1);\n                    num_temp <= (int_part_reg * (pow10_K * (pow10_R - 64'd1))) +\n                                ((A * pow10_R) + B - A);\n                end\n                FINISH: begin\n                    numerator <= num_temp;\n                    denominator <= denom_temp;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\n    // Power of 10 function (10^n for 0 <= n <= 11)\n    function [63:0] pow10_func;\n        input [3:0] n;\n        begin\n            case(n)\n                4'd0: pow10_func = 64'd1;\n                4'd1: pow10_func = 64'd10;\n                4'd2: pow10_func = 64'd100;\n                4'd3: pow10_func = 64'd1000;\n                4'd4: pow10_func = 64'd10000;\n                4'd5: pow10_func = 64'd100000;\n                4'd6: pow10_func = 64'd1000000;\n                4'd7: pow10_func = 64'd10000000;\n                4'd8: pow10_func = 64'd100000000;\n                4'd9: pow10_func = 64'd1000000000;\n                4'd10: pow10_func = 64'd10000000000;\n                4'd11: pow10_func = 64'd100000000000;\n                default: pow10_func = 64'd0;\n            endcase\n        end\n    endfunction\n\nendmodule